import {
  openTileCache,
  type StoredObject,
  type TileCache,
  type TileCacheOptions,
} from "@stallion/client-store";
import {
  type BBox,
  type LevelRange,
  type Tile,
  tileKey,
  type ViewTiles,
  viewTiles,
} from "@stallion/geometry";
import {
  BOARD_KEY,
  decode,
  decodeFrame,
  encode,
  encodeFrame,
  encodeMove,
  type FrameKind,
} from "@stallion/schema";
import { Encoder } from "cbor-x";
import * as decoding from "lib0/decoding";
import * as encoding from "lib0/encoding";
import {
  Awareness,
  applyAwarenessUpdate,
  encodeAwarenessUpdate,
  removeAwarenessStates,
} from "y-protocols/awareness";
import { readSyncMessage, writeUpdate } from "y-protocols/sync";
import * as Y from "yjs";
import {
  type BoardLock,
  boardEndpoint,
  type Fetch,
  isLockReason,
  localPasses,
  networkRefusal,
  type PassStore,
  type PinResult,
  type PinState,
  passOf,
  pinSetOf,
  readJson,
  refusalOf,
  type SetPinResult,
} from "./pin";
import {
  type Backoff,
  type Connect,
  connectWebSocket,
  DEFAULT_BACKOFF,
  retryDelay,
} from "./socket";

export type { Connect, SocketHandlers, SyncSocket } from "./socket";

export type LiveObjects = ReadonlyMap<string, StoredObject> & {
  observe(listener: (changed: ReadonlySet<string>) => void): () => void;
};

export type BoardStatus = "Connecting" | "Open" | "Offline" | "NeedsPin" | "Closed";

export type BoardError = { tileKey: string; reason: string };

export type BoardOptions = {
  localOnly?: boolean;
  connect?: Connect;
  cache?: TileCacheOptions;
  backoff?: Backoff;
  fetch?: Fetch;
  passes?: PassStore;
  onError?: (error: BoardError) => void;
  onStatus?: (status: BoardStatus) => void;
};

export type History = {
  undo(): void;
  redo(): void;
  checkpoint(): void;
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  observe(listener: () => void): () => void;
};

export type StallionBoard = {
  setView(viewport: BBox, zoom: number): void;
  put(stored: StoredObject): void;
  remove(objectId: string): void;
