import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const CONFIG_DIR = join(homedir(), ".config", "stallion");
const ACCESS_ENV = join(CONFIG_DIR, "access-env");

const parseEnv = (text) =>
  Object.fromEntries(
    text
      .split("\n")
      .map((l) => l.replace(/^\s*export\s+/, "").trim())
      .filter((l) => l && !l.startsWith("#") && l.includes("="))
      .map((l) => {
        const at = l.indexOf("=");
        return [l.slice(0, at), l.slice(at + 1).replace(/^(["'])(.*)\1$/, "$2")];
      }),
  );

const readEnvFile = (p) => (existsSync(p) ? parseEnv(readFileSync(p, "utf8")) : {});

const accessHeaders = () => {
  const file = readEnvFile(ACCESS_ENV);
  const id = process.env.CF_ACCESS_CLIENT_ID || file.CF_ACCESS_CLIENT_ID;
  const secret = process.env.CF_ACCESS_CLIENT_SECRET || file.CF_ACCESS_CLIENT_SECRET;
  return id && secret ? { "CF-Access-Client-Id": id, "CF-Access-Client-Secret": secret } : {};
};

const randomBoardId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let value = 0n;
  for (const b of bytes) value = (value << 8n) | BigInt(b);
  return value.toString(36).padStart(25, "0");
};

const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const DEVICE = "Galaxy Tab S9";
const SHOTS_ROOT = join(homedir(), "development", ".tmp", "stallion-reload");

const watchPage = (page) => {
  const problems = [];
  page.on("console", (message) => {
    if (message.type() !== "error") return;
    problems.push(`console error: ${message.text()}`);
  });
  page.on("pageerror", (error) => problems.push(`page error: ${error.message}`));
  return problems;
};

const isExpected = (message) =>
  /favicon/.test(message) || /Failed to load resource.*401/.test(message) || /401 \(Unauthorized\)/.test(message);

async function offlineReconnectCheck({ browser, devices, dir }) {
  const boardId = randomBoardId();
  const url = `${ORIGIN}/b/${boardId}`;
  const context = await browser.newContext({
    ...devices[DEVICE],
    extraHTTPHeaders: accessHeaders(),
    serviceWorkers: "allow",
  });
  const page = await context.newPage();
  const problems = watchPage(page);
  try {
    await page.goto(url, { waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15_000 });
    await page.waitForFunction(
      () => document.querySelector("[data-connection]")?.getAttribute("data-connection") === "Connected",
      undefined,
      { timeout: 15_000 },
    );
    await page.evaluate(() => navigator.serviceWorker.ready);
    await page.waitForTimeout(500);

    await context.setOffline(true);
    await page.reload({ waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15_000 });

    await page.waitForTimeout(12_000);

