    await notice.waitFor({ state: "visible", timeout: 5_000 });
    const button = notice.getByRole("button", { name: "Reload" });
    await button.waitFor({ state: "visible" });
    const box = await button.boundingBox();

    const shotPath = join(dir, "offline-bar.png");
    writeFileSync(shotPath, await page.screenshot());

    await context.setOffline(false);
    await notice.waitFor({ state: "hidden", timeout: 20_000 });
    const afterShotPath = join(dir, "reconnected.png");
    writeFileSync(afterShotPath, await page.screenshot());

    return {
      boardId,
      buttonHeight: box?.height,
      meetsTouchTarget: (box?.height ?? 0) >= 44,
